    const png_data = arena.allocator().dupe(u8, png_buffer[0..@intCast(png_size)]) catch {
        try request.respond("Memory error", .{.status = .internal_server_error});
        return;
    };

    stb_image_write.stbi_write_free(png_buffer);

    try request.respond(png_data, .{
        .status = .ok,
        .content_type = .{ .mime_type = "image/png" },
    });
}

fn applySharpenFilter(data: []u8, width: i32, height: i32, arena: *ArenaAllocator) void {
    const w = @as(usize, @intCast(width));
    const h = @as(usize, @intCast(height));
    const channels: usize = 4;

    const kernel: [9]f32 = .{
        0.0, -1.0, 0.0,
        -1.0, 5.0, -1.0,
        0.0, -1.0, 0.0,
    };

    const temp = arena.allocator().alloc(u8, data.len) catch return;
    @memcpy(temp, data);

    var y: usize = 1;
    while (y < h - 1) : (y += 1) {
        var x: usize = 1;
        while (x < w - 1) : (x += 1) {
            var c: usize = 0;
            while (c < channels) : (c += 1) {
                var sum: f32 = 0.0;
                var ky: i32 = -1;
                while (ky <= 1) : (ky += 1) {
                    var kx: i32 = -1;
                    while (kx <= 1) : (kx += 1) {
                        const pixel_idx = (y + @as(usize, @intCast(ky))) * w * channels + (x + @as(usize, @intCast(kx))) * channels + c;
                        const kernel_idx = (@as(usize, @intCast(ky + 1))) * 3 + @as(usize, @intCast(kx + 1));
                        sum += @as(f32, @floatFromInt(temp[pixel_idx])) * kernel[kernel_idx];
                    }
                }
                const out_idx = y * w * channels + x * channels + c;
                if (out_idx < data.len) {
                    const clamped = @max(0.0, @min(255.0, sum));
                    data[out_idx] = @intFromFloat(clamped);
                }
            }
        }
    }

    arena.allocator().free(temp);
}

const std = @import("std");
const build = std.build;

pub fn build(b: *build.Builder) !void {
    const target = b.standardTargetOptions(.{});
    const mode = b.standardReleaseOptions(.{});

    const exe = b.addExecutable("image-server", "src/main.zig");
    exe.set_target(target);
    exe.set_build_mode(mode);

    exe.addPackagePath("memory", "src/core/memory.zig");
    exe.addPackagePath("tensor", "src/core/tensor.zig");
    exe.addPackagePath("types", "src/core/types.zig");
    exe.addPackagePath("image_processor", "src/image_processor.zig");

    exe.addIncludeDir("src/include");
    exe.addIncludeDir("src/halide/include");

    b.default_step.dependOn(&exe.step);

    exe.install();

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.setArgs(b.args);
}
